// ============================================================
// FORMAT ATTRIBUTES RESPONSE
// ============================================================
// Transforms the raw WooCommerce attributes response into a
// clean structure for the frontend.

const inputItems = $input.all();

try {
  let rawData = inputItems[0]?.json;
  let attributes = [];

  if (Array.isArray(rawData)) {
    attributes = rawData;
  } else if (inputItems.length > 1 || (rawData && rawData.id)) {
    // n8n splits array responses into separate items
    attributes = inputItems.map(item => item.json);
  }

  // Map to clean format
  const cleanAttributes = attributes
    .filter(attr => attr && attr.id)
    .map(attr => ({
      id: attr.id,
      name: attr.name || '',
      slug: attr.slug || '',
      type: attr.type || 'select',
      order_by: attr.order_by || 'menu_order',
      has_archives: attr.has_archives || false
    }));

  return [{
    json: {
      success: true,
      attributes: cleanAttributes
    }
  }];
} catch (error) {
  return [{
    json: {
      success: false,
      message: 'Failed to fetch attributes: ' + error.message,
      attributes: []
    }
  }];
}
